using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CasinoFenceGlow{static CasinoFenceGlow(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||!File.Exists("CasinoFenceGlow.request"))return;File.Delete("CasinoFenceGlow.request");try{Build();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CasinoFenceGlow.txt",e.ToString());Debug.LogException(e);}}
static void Build(){string dir="Assets/Scenes/Oasis/LandmarkBoundaryFences";int vertices=0,meshes=0;foreach(var id in AssetDatabase.FindAssets("t:Mesh",new[]{dir})){var path=AssetDatabase.GUIDToAssetPath(id);if(!Path.GetFileName(path).StartsWith("Casino Diamonds"))continue;var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);var backup="FinalEnvironmentRoadBackup/BeforeCasinoFenceGlow/"+Path.GetFileName(path);if(!File.Exists(backup))File.Copy(path,backup);var c=m.colors;var info=m.uv2;int marked=0;for(int i=0;i<c.Length;i++){bool gold=c[i].r>.42f&&c[i].g>.24f&&c[i].g<.38f&&c[i].b<.15f&&c[i].r>c[i].g*1.3f;info[i].y=gold?1:0;if(gold)marked++;}m.uv2=info;m.UploadMeshData(false);EditorUtility.SetDirty(m);vertices+=marked;meshes++;}if(vertices==0)throw new Exception("No casino gold vertices located");var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/GardenUtilityAtlas/City Garden Utility Atlas.mat");if(!mat)throw new Exception("Existing shared material missing");AssetDatabase.ImportAsset(AssetDatabase.GetAssetPath(mat.shader),ImportAssetOptions.ForceUpdate);mat.SetFloat("_FenceGoldGlow",2.3f);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();if(ShaderUtil.ShaderHasError(mat.shader))throw new Exception("Casino fence shader errors");var sc=SceneManager.GetActiveScene();var module=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true)).First(l=>l.name.StartsWith("Casino Diamonds")&&l.name.Contains("8m"));var mid=module.transform.TransformPoint(new Vector3(4,.65f,0));var cnight=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=cnight.IsNight;try{cnight.Apply(true);var cap=typeof(CityTaxiStandBuild).GetMethod("Capture",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);cap.Invoke(null,new object[]{sc,mid-module.transform.forward*4.7f+Vector3.up*.75f,mid,"Casino-Fence-Gold-Glow"});}finally{cnight.Apply(night);}File.WriteAllText("FinalEnvironmentRoadReview/CasinoFenceGlow.txt","SUCCESS: existing casino diamond ornaments, gold pillar bands and top/skirting trim selectively emit warm gold. Stone and black metal unlit. Shared casino module assets updated="+meshes+", marked existing vertices="+vertices+". Existing mesh geometry, colliders, LODs and prefab links retained. Same garden atlas material/textures; no new meshes, renderers, textures, materials, realtime lights or texture samples. Other garden/fence styles have no emission marker and remain unchanged. Strength=2.3, night linked. Shader errors=0.");}}
